contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address who) public payable {
        require(who != address(0));
        uint256 beforeBalance = c.balances(who); if (__ESBMC_reverted()) return;
        uint256 beforeReserve = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = c.balances(who); if (__ESBMC_reverted()) return;
        uint256 afterReserve = address(c).balance;

        assert(reverted == (beforeBalance == 0 || address(c).balance < beforeBalance)
            || (!reverted && afterBalance == 0 && afterReserve == beforeReserve - beforeBalance));
    }

    receive() external payable {}
}

